// Benchmark boilerplate generated by Benchmark

import Benchmark
import SolidPostScript

let benchmarks: @Sendable () -> Void = {
  let configuration = Benchmark.Configuration(
    metrics: [.wallClock, .cpuTotal, .mallocCountTotal, .peakMemoryResidentDelta],
    warmupIterations: 3,
    scalingFactor: .one,
    maxDuration: .seconds(10),
    maxIterations: 100
  )

  let catalog = GraphicsMediaCatalog(
    sources: Dictionary(uniqueKeysWithValues: (0..<100_000).map { position in
      (position, GraphicsMediaSource(
        position: position,
        attributes: GraphicsMediaAttributes(pageSize: GraphicsSize(
          width: Double(100 + position % 1_000),
          height: Double(200 + position / 1_000)
        ))
      ))
    }),
    priority: Array((0..<100_000).reversed())
  )
  let provider = StandardGraphicsPageDeviceProvider(
    physicalCapabilities: .printSpool,
    inputMedia: catalog
  )
  let session = try! provider.makeSession(for: .letter)
  let mediaRequest = GraphicsPageDeviceRequest(
    pageSize: GraphicsSize(width: 1_099, height: 299),
    resolution: GraphicsSize(width: 72, height: 72),
    imagingBoundingBox: nil,
    numberOfCopies: 1,
    inputMedia: catalog,
    mediaRequest: GraphicsMediaRequest(
      attributes: GraphicsMediaAttributes(pageSize: GraphicsSize(width: 1_099, height: 299))
    )
  )

  Benchmark("100,000-Source Media Match", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      blackHole(try! session.negotiate(mediaRequest))
    }
  }

  let pageSnapshot = GraphicsStateSnapshot(
    matrix: .identity,
    path: .init(),
    clip: .init(imageableBounds: GraphicsDeviceDescriptor.letter.imageableBounds),
    paint: .deviceGray(0),
    lineWidth: 1,
    lineCap: .butt,
    lineJoin: .miter,
    miterLimit: 10,
    dash: .init()
  )
  let showPage = GraphicsEvent(operation: .page(.show), before: pageSnapshot, after: pageSnapshot)
  let duplexPlacement = GraphicsPagePlacement(isDuplex: true)
  let collatedDelivery = GraphicsPageDeliveryConfiguration(collates: true)
  Benchmark("50-Page 20-Copy Collation", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let renderer = PrintSpoolGraphicsTarget().makeRenderer()
      renderer.activateDevice(pageSnapshot.device)
      for ordinal in 1...50 {
        try! renderer.transmitPage(showPage, transmission: GraphicsPageTransmission(
          trigger: .showPage,
          logicalOrdinal: ordinal,
          copies: 20,
          placement: duplexPlacement,
          delivery: collatedDelivery
        ))
      }
      blackHole(try! renderer.finish())
    }
  }

  Benchmark("1,000-Page Duplex Packing", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let renderer = PrintSpoolGraphicsTarget().makeRenderer()
      renderer.activateDevice(pageSnapshot.device)
      for ordinal in 1...1_000 {
        try! renderer.transmitPage(showPage, transmission: GraphicsPageTransmission(
          trigger: .showPage,
          logicalOrdinal: ordinal,
          copies: 1,
          placement: duplexPlacement
        ))
      }
      blackHole(try! renderer.finish())
    }
  }
}
